class Solution(object):
    def longestOnes(self, A, K):
        """
        :type A: List[int]
        :type K: int
        :rtype: int
        """
        p1, cnt = 0, 0
        ans = 0
        for p2 in range(len(A)):
            if A[p2] == 0:
                cnt += 1
            while cnt > K and p1 < p2:
                if A[p1] == 0:
                    cnt -= 1
                p1 += 1
            if cnt <= K:
                ans = max(ans, p2 - p1 + 1)
        return ans
